(function () {
  'use strict';

  // --- URL helpers ---
  function normalizePath(p) {
    p = (p || '').toLowerCase();
    p = p.replace(/\/+$/, ''); // remove barras finais repetidas
    if (p === '') p = '/';
    return p;
  }

  var ALLOWED = (function(){
    var list = [
      '/solucion/placetopay',
      '/solucion/pay-at-the-table',
      '/solucion/pos',
      '/en/solution/placetopay',
      '/en/solution/pay-at-the-table',
      '/en/solution/pos',
      '/solucion/quioscos',
      '/en/solution/kiosks',
      '/solucion/smart-terminals',
      '/en/solution/smart-terminals',
      '/solucion/linga',
      '/en/solution/linga',
      '/solucion/aceptacion-de-pagos',
      '/solucion/link'
    ];
    var map = Object.create(null);
    for (var i=0; i<list.length; i++) map[normalizePath(list[i])] = true;
    return map;
  })();

  var currentPath = normalizePath((window.location && window.location.pathname) || '/');
  var IS_ALLOWED = !!ALLOWED[currentPath];

  function getPageSlug(path) {
    var parts = path.split('/').filter(Boolean); // ['lang','slug',...]
    return parts[1] || '';
  }
  var PAGE_SLUG = getPageSlug(currentPath); // 'placetopay' | 'pay-at-the-table' | 'pos' | ...
  var ECU_ALLOWED_ON_THIS_PAGE = (PAGE_SLUG === 'placetopay');

  // --- Helpers ---
  function isVisible(el) { return !!(el && el.offsetParent !== null); }
  function getContainer() { return document.getElementById('box-form'); }
  function q(container, sel) { return container ? container.querySelector(sel) : null; }
  function hide(el) { if (el) el.style.setProperty('display', 'none', 'important'); }
  function show(el) { if (el) el.style.removeProperty('display'); }

  function apply() {
    var box = getContainer();
    if (!box) return;

    // Coleta apenas dentro do container
    var formPR  = q(box, '#form-merchants-pr') || q(box, '#form-merhcants-pr') || q(box, '#form-placetopay-pr');
    var formECU = q(box, '#form-placetopay-ecu-co');
    var formSTD = q(box, '#form-std');
    if (!formSTD) return;

    if (!IS_ALLOWED) {
      // Fora da lista: STD deve ser o único visível
      show(formSTD);
      hide(formPR);
      hide(formECU);
      return;
    }

    // Em páginas ALLOWED
    if (!ECU_ALLOWED_ON_THIS_PAGE) {
      // ECU/CO não é permitido fora de 'placetopay'
      hide(formECU);
    }

    var prVisible  = isVisible(formPR);
    var ecuVisible = ECU_ALLOWED_ON_THIS_PAGE && isVisible(formECU);
    var anyGeoVisible = prVisible || ecuVisible;

    if (anyGeoVisible) hide(formSTD); else show(formSTD);
  }

  // === Mecânica do snippet original ===
  var observer = new MutationObserver(apply);
  observer.observe(document.documentElement, {
    subtree: true,
    childList: true,
    attributes: true,
    attributeFilter: ['style', 'class']
  });

  var tries = 0;
  var checker = setInterval(function () {
    apply();
    if (++tries > 40) clearInterval(checker); // ~12s
  }, 300);

  window.addEventListener('load', apply);
  document.addEventListener('DOMContentLoaded', apply);

  // Primeira aplicação
  apply();
})();
